mapper.select:
SELECT EXISTS (
SELECT 1
FROM company_detail
WHERE company_name = #{companyName}
) AS isDuplicate

SELECT company_name
FROM company_detail
WHERE company_id = #{companyId}

mapper.update:
UPDATE company
SET is_deleted = 1
WHERE company_id = #{companyId}

mapper.select:
SELECT count(*) > 0
FROM company_follow f
JOIN company c ON f.company_id = c.company_id
WHERE f.company_id = #{companyId}
    AND f.user_id = #{userId}
    AND c.is_deleted = false
